'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),http=require('node:http'),{execFileSync}=require('node:child_process'),{verifier}=require('../generateurs/compresser-catalogues-i18n.cjs');
const root=path.resolve(__dirname,'../..'),read=f=>fs.readFileSync(path.join(root,f),'utf8'),base='ca0b6885dde4806aaefa59498625a05fd5244ac0',old=f=>execFileSync('git',['show',base+':'+f],{cwd:root,encoding:'utf8',maxBuffer:4e6}),manifest=()=>verifier(),proofPath=path.join(root,'outils/audits/I18N-NOTIFICATIONS-CORPS-871-preuve.json'),proof=fs.existsSync(proofPath)?JSON.parse(fs.readFileSync(proofPath)):null,snapshot=f=>proof?execFileSync('git',['show',proof.codeCommit+':'+f],{cwd:root,encoding:'utf8',maxBuffer:4e6}):read(f);
test('transport : tous les catalogues restitués octet pour octet, sources antérieures inchangées',()=>{const m=manifest();assert.ok(m.files.length>=84);for(const f of m.files)if(f.source!=='i18n/toast-bodies-resources.js')assert.equal(snapshot(f.source),old(f.source),f.source);const original=execFileSync('git',['show','db7cc52676d3aebb20f1878bc4d9d6d3434fb7a1:i18n/toast-bodies-resources.js'],{cwd:root,encoding:'utf8',maxBuffer:4e6}),rows=s=>s.match(/\/\*ROWS\*\/([\s\S]*?)\/\*FIN\*\//)[1];assert.equal(rows(snapshot('i18n/toast-bodies-resources.js')),rows(original),'les 1 429 × neuf valeurs de Claude restent strictement identiques');assert.ok(m.files.reduce((s,f)=>s+f.packedBytes,0)<m.files.reduce((s,f)=>s+f.sourceBytes,0)*.4);});
test('transport : seuls des fichiers i18n statiques sont routés, API/crons/images inchangés',()=>{const current=JSON.parse(read('vercel.json')),before=JSON.parse(old('vercel.json'));const routes=current.rewrites.filter(r=>r.source.startsWith('/i18n/')),headers=current.headers.filter(r=>r.source.startsWith('/i18n/'));assert.equal(routes.length,1);assert.equal(headers.length,1);assert.equal(routes[0].destination,'/i18n/packed/:catalog.js.br');assert.deepEqual(Object.fromEntries(headers[0].headers.map(h=>[h.key,h.value])),{'Content-Encoding':'br','Content-Type':'application/javascript; charset=utf-8','Vary':'Accept-Encoding'});const historical=JSON.parse(snapshot('vercel.json'));historical.rewrites=historical.rewrites.filter(r=>!r.source.startsWith('/i18n/'));historical.headers=historical.headers.filter(r=>!r.source.startsWith('/i18n/'));assert.deepEqual(historical,before);const ignore=read('.vercelignore');assert.ok(snapshot('.vercelignore').startsWith(old('.vercelignore')));const block=ignore.match(/# BEGIN RP_I18N_PACKED_SOURCES\n([\s\S]*?)\n# END RP_I18N_PACKED_SOURCES/)[1].split('\n');assert.deepEqual(block,manifest().files.map(f=>f.source));for(const f of block)assert.match(f,/^i18n\/[A-Za-z0-9_-]*resources\.js$/);});
test('Chromium : décompression HTTP native des catalogues, neuf langues et zéro requête lors des bascules',async()=>{const {chromium}=require('playwright'),m=manifest(),map=new Map(m.files.map(f=>['/'+f.source,f])),requests=[];const server=http.createServer((req,res)=>{const url=new URL(req.url,'http://fixture'),f=map.get(url.pathname);requests.push(url.pathname);if(!f){res.writeHead(404);res.end();return;}res.writeHead(200,{'Content-Encoding':'br','Content-Type':'application/javascript; charset=utf-8','Cache-Control':'no-store','Access-Control-Allow-Origin':'*'});res.end(fs.readFileSync(path.join(root,f.packed)));});await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+server.address().port,browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});try{const p=await browser.newPage(),errors=[],responses=[];p.on('pageerror',e=>errors.push(String(e)));p.on('response',r=>{if(new URL(r.url()).origin===origin)responses.push(r.body().then(body=>{const f=map.get(new URL(r.url()).pathname);assert.ok(body.equals(fs.readFileSync(path.join(root,f.source))),f.source+' : octets décodés par Chromium');}));});await p.setContent('<input id="saisie" value="question intacte"><div id="result-toast"><div id="toast-result"></div><div id="toast-sub"></div></div>');await p.addScriptTag({content:read('i18n/i18next.min.js')});await p.evaluate(()=>{window.RP_I18N_GAME_ENABLED=true;window.RPPlateauI18n={language:()=>i18next.language||'fr'};window.noterIncidentSession=()=>{};window.state={pa:8,arg:500,progression:{etape:3}};});const ordered=[m.files.find(f=>f.source==='i18n/resources.js'),...m.files.filter(f=>f.source!=='i18n/resources.js')];for(const f of ordered)await p.addScriptTag({url:origin+'/'+f.source});await Promise.all(responses);assert.equal(responses.length,m.files.length);await p.evaluate(async()=>{await i18next.init({lng:'fr',fallbackLng:'fr',resources:RP_I18N_RESOURCES,interpolation:{escapeValue:false}});});const core=read('plateau-core.js'),start=core.indexOf('function showToast('),end=core.indexOf('\n}',start)+2;await p.addScriptTag({content:core.slice(start,end)});const count=requests.length;const fr=await p.evaluate(()=>Object.values(RP_I18N_RESOURCES.fr.translation.toastBodies).find(x=>/^[A-Za-zÀ-ÿ]/.test(x)));const before=await p.evaluate(()=>JSON.stringify(state));for(const lang of ['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de']){const r=await p.evaluate(async({lang,fr})=>{await i18next.changeLanguage(lang);showToast('Info',fr,true);for(const cb of RP_I18N_CHANGE_CALLBACKS||[])cb(lang);const text=document.getElementById('toast-sub').textContent;showToast('Texte libre',fr,true,undefined,{bodySource:'player'});for(const cb of RP_I18N_CHANGE_CALLBACKS||[])cb(lang);return {text,expected:RPToastBodyI18n.label(fr),player:document.getElementById('toast-sub').textContent,input:document.getElementById('saisie').value,state:JSON.stringify(state)};},{lang,fr});assert.equal(r.text,r.expected);assert.equal(r.player,fr);assert.equal(r.input,'question intacte');assert.equal(r.state,before);}assert.equal(requests.length,count);assert.deepEqual(errors,[]);await p.close();}finally{await browser.close();await new Promise(r=>server.close(r));}});
